import atcoder/extra/monoid/monoid
import atcoder/extra/structure/offline_rectangle_add_point_get

proc addInt64(
    first,
    second:
      int64
): int64 =
  first + second

proc zeroInt64(): int64 =
  0'i64

proc negateInt64(
    value:
      int64
): int64 =
  -value

type
  AdditiveInt64Group =
    CommutativeGroupOf(
      int64,
      addInt64,
      zeroInt64,
      negateInt64,
    )

  Rectangle =
    tuple[
      xLeft,
      xRight,
      yLower,
      yUpper:
        int
    ]

  InitialRectangle =
    tuple[
      xLeft,
      xRight,
      yLower,
      yUpper:
        int,
      weight:
        int64
    ]

proc nextState(
    state:
      var uint64
): uint64 =
  state =
    state *
      6364136223846793005'u64 +
      1442695040888963407'u64

  state

proc nextInt(
    state:
      var uint64,
    bound:
      int
): int =
  doAssert bound > 0

  int(
    state.nextState mod
      uint64(
        bound
      )
  )

proc nextRectangle(
    state:
      var uint64
): Rectangle =
  let
    rawX1 =
      state.nextInt(101) - 50
    rawX2 =
      state.nextInt(101) - 50
    rawY1 =
      state.nextInt(101) - 50
    rawY2 =
      state.nextInt(101) - 50

  (
    xLeft:
      min(rawX1, rawX2),
    xRight:
      max(rawX1, rawX2),
    yLower:
      min(rawY1, rawY2),
    yUpper:
      max(rawY1, rawY2),
  )

proc nextWeight(
    state:
      var uint64
): int64 =
  int64(
    state.nextInt(
      2001
    ) - 1000
  )

