proc checkAnswers(
    answers:
      seq[int64],
    expectedOffset,
    expectedCount:
      int
) =
  doAssert answers.len ==
    expectedCount

  for index in 0 ..<
      expectedCount:
    doAssert answers[index] ==
      OracleExpected[
        expectedOffset +
          index
      ]

block deterministicRandomDifferential:
  var state =
    20260808'u64

  for scenarioIndex in 0 ..<
      RandomScenarioCount:
    let initialCount =
      state.nextInt(8)

    var initialRectangles =
      newSeq[
        InitialRectangle
      ]()

    for initialIndex in 0 ..<
        initialCount:
      let rectangle =
        state.nextRectangle()

      initialRectangles.add(
        (
          xLeft:
            rectangle.xLeft,
          xRight:
            rectangle.xRight,
          yLower:
            rectangle.yLower,
          yUpper:
            rectangle.yUpper,
          weight:
            state.nextWeight(),
        )
      )

      discard initialIndex

    var solver =
      initOfflineRectangleAddPointGet[
        AdditiveInt64Group
      ](
        initialRectangles,
        AdditiveInt64Group,
      )

    for pairIndex in 0 ..<
        RandomQueriesPerScenario:
      let queryFirst =
        state.nextInt(2) == 0

      if queryFirst:
        let
          x =
            state.nextInt(141) - 70
          y =
            state.nextInt(141) - 70

        let queryIndex =
          solver.addPointQuery(
            x,
            y,
          )

        doAssert queryIndex ==
          pairIndex

        let rectangle =
          state.nextRectangle()

        solver.addRectangle(
          rectangle.xLeft,
          rectangle.xRight,
          rectangle.yLower,
          rectangle.yUpper,
          state.nextWeight(),
        )
      else:
        let rectangle =
          state.nextRectangle()

        solver.addRectangle(
          rectangle.xLeft,
          rectangle.xRight,
          rectangle.yLower,
          rectangle.yUpper,
          state.nextWeight(),
        )

        let
          x =
            state.nextInt(141) - 70
          y =
            state.nextInt(141) - 70

        let queryIndex =
          solver.addPointQuery(
            x,
            y,
          )

        doAssert queryIndex ==
          pairIndex

    doAssert solver.queryCount ==
      RandomQueriesPerScenario

    solver.solve().checkAnswers(
      RandomOffset +
        scenarioIndex *
          RandomQueriesPerScenario,
      RandomQueriesPerScenario,
    )

block integerBoundaryDifferential:
  for scenarioIndex in 0 ..<
      BoundaryScenarioCount:
    let
      weight1 =
        int64(
          scenarioIndex mod 17 - 8
        )
      weight2 =
        int64(
          scenarioIndex mod 19 + 1
        )
      weight3 =
        int64(
          scenarioIndex mod 13 - 6
        )
      delta1 =
        int64(
          scenarioIndex mod 23 - 11
        )
      delta2 =
        int64(
          scenarioIndex mod 29 - 14
        )

    var solver =
      initOfflineRectangleAddPointGet[
        AdditiveInt64Group
      ](
        @[
          (
            xLeft: low(int),
            xRight: low(int) + 2,
            yLower: low(int),
            yUpper: low(int) + 3,
            weight: weight1,
          ),
          (
            xLeft: high(int) - 2,
            xRight: high(int),
            yLower: high(int) - 3,
            yUpper: high(int),
            weight: weight2,
          ),
          (
            xLeft: low(int),
            xRight: high(int),
            yLower: low(int),
            yUpper: high(int),
            weight: weight3,
          ),
          (
            xLeft: 0,
            xRight: 0,
            yLower: -1,
            yUpper: 1,
            weight: 99'i64,
          ),
        ],
        AdditiveInt64Group,
      )

    discard solver.addPointQuery(
      low(int),
      low(int),
    )

    discard solver.addPointQuery(
      high(int) - 1,
      high(int) - 1,
    )

    solver.addRectangle(
      low(int),
      high(int),
      low(int),
      high(int),
      delta1,
    )

    discard solver.addPointQuery(
      0,
      0,
    )

    discard solver.addPointQuery(
      high(int),
      high(int) - 1,
    )

    solver.addRectangle(
      low(int),
      low(int) + 2,
      low(int),
      high(int),
      delta2,
    )

    discard solver.addPointQuery(
      low(int) + 1,
      low(int) + 2,
    )

    discard solver.addPointQuery(
      low(int) + 2,
      low(int),
    )

    solver.addRectangle(
      0,
      0,
      -1,
      1,
      123'i64,
    )

    discard solver.addPointQuery(
      high(int) - 2,
      high(int) - 3,
    )

    discard solver.addPointQuery(
      high(int),
      high(int),
    )

    doAssert solver.queryCount ==
      BoundaryQueriesPerScenario

    solver.solve().checkAnswers(
      BoundaryOffset +
        scenarioIndex *
          BoundaryQueriesPerScenario,
      BoundaryQueriesPerScenario,
    )

block directedSemantics:
  for scenarioIndex in 0 ..<
      DirectedScenarioCount:
    var initialRectangles =
      newSeq[
        InitialRectangle
      ]()

    if scenarioIndex == 1:
      initialRectangles.add(
        (
          xLeft: -2,
          xRight: 3,
          yLower: -1,
          yUpper: 4,
          weight: 5'i64,
        )
      )

      initialRectangles.add(
        (
          xLeft: -2,
          xRight: 3,
          yLower: -1,
          yUpper: 4,
          weight: -2'i64,
        )
      )

      initialRectangles.add(
        (
          xLeft: 1,
          xRight: 1,
          yLower: -9,
          yUpper: 9,
          weight: 100'i64,
        )
      )

    elif scenarioIndex >= 2:
      let
        shift =
          scenarioIndex mod 7 - 3
        weight1 =
          int64(
            scenarioIndex mod 11 - 5
          )
        weight2 =
          int64(
            scenarioIndex mod 13 - 6
          )

      initialRectangles.add(
        (
          xLeft: -2 + shift,
          xRight: 3 + shift,
          yLower: -1,
          yUpper: 4,
          weight: weight1,
        )
      )

      initialRectangles.add(
        (
          xLeft: -2 + shift,
          xRight: 3 + shift,
          yLower: -1,
          yUpper: 4,
          weight: weight2,
        )
      )

      initialRectangles.add(
        (
          xLeft: 7,
          xRight: 7,
          yLower: -3,
          yUpper: 3,
          weight: 55'i64,
        )
      )

    var solver =
      initOfflineRectangleAddPointGet[
        AdditiveInt64Group
      ](
        initialRectangles,
        AdditiveInt64Group,
      )

    if scenarioIndex == 0:
      const points = [
        (-10, -10),
        (-1, 0),
        (0, 0),
        (1, 1),
        (10, 10),
      ]

      for point in points:
        discard solver.addPointQuery(
          point[0],
          point[1],
        )

      discard solver.addPointQuery(
        low(int),
        low(int),
      )

      discard solver.addPointQuery(
        high(int),
        high(int),
      )

      discard solver.addPointQuery(
        0,
        high(int),
      )

    elif scenarioIndex == 1:
      const points = [
        (-2, -1),
        (2, 3),
        (3, 0),
        (-3, 0),
        (0, 4),
        (0, -2),
        (1, 1),
        (100, 100),
      ]

      for point in points:
        discard solver.addPointQuery(
          point[0],
          point[1],
        )

    else:
      let
        shift =
          scenarioIndex mod 7 - 3
        delta =
          int64(
            scenarioIndex mod 17 - 8
          )
        weight4 =
          int64(
            scenarioIndex mod 19 - 9
          )

      discard solver.addPointQuery(
        -2 + shift,
        -1,
      )

      discard solver.addPointQuery(
        3 + shift,
        -1,
      )

      solver.addRectangle(
        0 + shift,
        5 + shift,
        0,
        5,
        delta,
      )

      discard solver.addPointQuery(
        1 + shift,
        1,
      )

      discard solver.addPointQuery(
        5 + shift,
        1,
      )

      solver.addRectangle(
        0 + shift,
        5 + shift,
        0,
        5,
        -delta,
      )

      discard solver.addPointQuery(
        1 + shift,
        1,
      )

      solver.addRectangle(
        2,
        6,
        3,
        3,
        999'i64,
      )

      discard solver.addPointQuery(
        -2 + shift,
        3,
      )

      solver.addRectangle(
        -5 + shift,
        -1 + shift,
        -5,
        -1,
        weight4,
      )

      discard solver.addPointQuery(
        -3 + shift,
        -3,
      )

      discard solver.addPointQuery(
        100,
        100,
      )

    doAssert solver.queryCount ==
      DirectedQueriesPerScenario

    let answers =
      solver.solve()

    answers.checkAnswers(
      DirectedOffset +
        scenarioIndex *
          DirectedQueriesPerScenario,
      DirectedQueriesPerScenario,
    )

    if scenarioIndex == 0:
      doAssert solver.solve() ==
        answers

block updatesOnlyAndEmptyRectangles:
  var solver =
    initOfflineRectangleAddPointGet[
      AdditiveInt64Group
    ](
      newSeq[
        InitialRectangle
      ](),
      AdditiveInt64Group,
    )

  solver.addRectangle(
    -10,
    10,
    -20,
    20,
    7'i64,
  )

  solver.addRectangle(
    5,
    5,
    -100,
    100,
    999'i64,
  )

  doAssert solver.queryCount == 0
  doAssert solver.solve().len == 0

type
  Box =
    object
      value:
        int64

proc addBox(
    first,
    second:
      Box
): Box =
  Box(
    value:
      first.value +
        second.value
  )

proc zeroBox(): Box =
  Box(
    value: 0
  )

proc inverseBox(
    value:
      Box
): Box =
  Box(
    value:
      -value.value
  )

type
  BoxGroup =
    CommutativeGroupOf(
      Box,
      addBox,
      zeroBox,
      inverseBox,
    )

block genericGroupInstantiation:
  var solver =
    initOfflineRectangleAddPointGet[
      BoxGroup
    ](
      newSeq[
        tuple[
          xLeft,
          xRight,
          yLower,
          yUpper:
            int,
          weight:
            Box
        ]
      ](),
      BoxGroup,
    )

  doAssert solver.queryCount == 0
  doAssert solver.solve().len == 0

doAssert TotalQueryEvaluations == 17920

echo(
  "OFFLINE_RECTANGLE_ADD_POINT_GET_CONTRACT_OK ",
  "queries=",
  TotalQueryEvaluations,
  " oracle=",
  OracleSerializationSha256,
)
